import ast,copy,hashlib,importlib.util,json
from pathlib import Path
root=Path('/workspace');p=json.loads((root/'proposal.json').read_text());r=json.load(open('/tmp/r001_resolved.json'))
if importlib.util.find_spec('jsonschema'):
 import jsonschema
 jsonschema.validate(p['study'],r['study_schema']); print('study schema PASS')
else:
 schema=r['study_schema']
 def validate(x,s,path='"'$'"'):
  ts={'object':dict,'array':list,'string':str,'boolean':bool}
  if 'type' in s: assert isinstance(x,ts[s['type']]),path
  if 'enum' in s: assert x in s['enum'],path
  if 'const' in s: assert x==s['const'],path
  if isinstance(x,dict):
   assert set(s.get('required',[]))<=x.keys(),path
   if s.get('additionalProperties') is False: assert set(x)<=set(s['properties']),path
   for k,v in x.items():
    if k in s.get('properties',{}): validate(v,s['properties'][k],path+'.'+k)
  if isinstance(x,list):
   assert len(x)>=s.get('minItems',0),path
   for i,v in enumerate(x):validate(v,s.get('items',{}),path+str(i))
  if isinstance(x,str): assert len(x)>=s.get('minLength',0),path
 validate(p['study'],schema);print('study schema PASS (recursive built-in checker; jsonschema absent)')
allowed=set(r['context']['allowed_observation_ids'])
assert set(p['study']['evidence_refs'])<=allowed
assert p['parent_trial'] in allowed
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert 1<=len(p['variants'])<=4
assert len({v['name'] for v in p['variants']})==len(p['variants'])
assert any(v['role']=='candidate' for v in p['variants'])
allowed_imports={'torch','numpy','math','typing','copy','functools','collections','itertools','dataclasses','contextlib','unirank','model_zoo'}
base=ast.parse((root/'history_g0_r0014_curvature_task.py').read_text())
# Removing a false guard is the sole structural change to the archived class.
base_class=next(n for n in base.body if isinstance(n,ast.ClassDef))
for fun in base_class.body:
 if isinstance(fun,ast.FunctionDef) and fun.name=='__init__':
  kept=[]
  for n in fun.body:
   if isinstance(n,ast.If) and ast.unparse(n.test)==\"residual_routing "'!= '"'task'\": continue
   kept.append(n)
  fun.body=kept

def normalize(tree):
 tree=copy.deepcopy(tree)
 tree.body=[n for n in tree.body if not (isinstance(n,ast.Expr) and isinstance(n.value,ast.Constant) and isinstance(n.value.value,str))]
 for n in tree.body:
  if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets): n.value=ast.Constant(None)
 for n in ast.walk(tree):
  if isinstance(n,ast.FunctionDef) and n.name=='__init__':
   names=[a.arg for a in n.args.args][-len(n.args.defaults):]
   for i,name in enumerate(names):
    if name in ('curvature_detail','residual_routing'):n.args.defaults[i]=ast.Constant(None)
 return ast.dump(tree,include_attributes=False)
for v in p['variants']:
 f=root/v['file'];assert f.name==v['file'] and f.suffix=='.py'
 src=f.read_text();tree=ast.parse(src);compile(src,str(f),'exec')
 config=ast.literal_eval(next(n.value for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)))
 assert config==v['config']
 init=next(n for n in ast.walk(tree) if isinstance(n,ast.FunctionDef) and n.name=='__init__')
 defaults=dict(zip([a.arg for a in init.args.args][-len(init.args.defaults):],[ast.literal_eval(n) for n in init.args.defaults]))
 for k,val in config.items():
  d=defaults[k]
  assert list(d)==val if isinstance(d,tuple) else d==val,(k,d,val)
 assert config['residual_routing']=='shared'
 assert normalize(tree)==normalize(base),v['name']
 for n in ast.walk(tree):
  if isinstance(n,ast.Import):assert all(t.name.split('.')[0] in allowed_imports for t in n.names)
  if isinstance(n,ast.ImportFrom):assert n.module.split('.')[0] in allowed_imports
 assert not any(isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id in {'open','exec','eval','__import__'} for n in ast.walk(tree))
 print(v['name'],'syntax/config/default/import/API source parity PASS',hashlib.sha256(f.read_bytes()).hexdigest())
# Check reuse identities from authorized runtime, not a rewritten module.
for h in r['context']['history']:
 if h['id'].startswith('g0-r0014'):
  fname='history_'+h['id'].replace('-','_')+'.py'
  assert hashlib.sha256((root/fname).read_bytes()).hexdigest()==h['source_sha256']
  print(h['id'],'archive source/config unchanged PASS')
curv=next(h for h in r['context']['history'] if h['id']=='g0-r0014-curvature_task')
dup=next(h for h in r['context']['history'] if h['id']=='g0-r0014-duplicate_linear_task')
scr=next(h for h in r['context']['history'] if h['id']=='g0-r0014-scrambled_curvature_task')
print('task observed curvature-minus-duplicate',curv['validation']['auc']-dup['validation']['auc'])
print('task observed curvature-minus-scrambled',curv['validation']['auc']-scr['validation']['auc'])
# Model routing specification; not tensor/backward validation.
for bank in ([0.,0.,0.,0.],[1.,2.,3.,4.],[-1.,0.,2.,-5.]):
 shared=sum(bank)/len(bank)
 for idx in range(4):
  task=bank[idx]
  assert task==bank[idx] and shared==sum(bank)/4
print('routing algebra PASS; dynamic torch/BF16/gradient and host training NOT RUN')
print('torch available:',bool(importlib.util.find_spec('torch')))
print('all local checks PASS')
PY"

